/* DWARF original prototype: void SetSkillGroup(CHARACTER * this, BYTE bSkillGroup) */

void __thiscall CHARACTER::SetSkillGroup(CHARACTER *this,BYTE bSkillGroup)

{
  TPacketGCChangeSkillGroup p;
  
  if ((bSkillGroup < 3) && (4 < (this->m_points).level)) {
    (this->m_points).skill_group = bSkillGroup;
    p.skill_group = (this->m_points).skill_group;
    p.header = 'p';
    DESC::Packet((this->super_CEntity).m_lpDesc,&p,2);
  }
  return;
}
